/** Runs a GET as a query. A caller-supplied `query.queryKey` wins over `defaultKey`. */
function useApiQuery<T, TError, TData>(
  defaultKey: QueryKey,
  fetcher: (options: RequestInit) => Promise<T>,
  options?: QueryHookOptions<T, TError, TData>,
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryKey = options?.query?.queryKey ?? defaultKey;
  const queryFn: QueryFunction<T> = ({ signal }) => fetcher({ signal, ...options?.request });
  const queryOptions = { queryKey, queryFn, ...options?.query } as UseQueryOptions<T, TError, TData> & { queryKey: QueryKey };
  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & { queryKey: QueryKey };
  return { ...query, queryKey: queryOptions.queryKey };
}

/** Builds a query hook for an endpoint that takes no parameters. */
const makeQuery = <T>(queryKey: QueryKey, fetcher: (options?: RequestInit) => Promise<T>) =>
  <TData = T, TError = ErrorType<unknown>>(options?: QueryHookOptions<T, TError, TData>) =>
    useApiQuery(queryKey, fetcher, options);

/**
 * Builds a mutation hook. `name` is the default mutationKey; the hook's variables are whatever
 * `mutate(...)` is given (`{ id }`, `{ data }`, `{ id, data }`, ...).
 */
const makeMutation = <TVars, T>(name: string, fn: (vars: TVars, request?: RequestInit) => Promise<T>) =>
  <TError = ErrorType<unknown>, TContext = unknown>(
    options?: MutationHookOptions<T, TError, TVars, TContext>,
  ): UseMutationResult<T, TError, TVars, TContext> =>
    useMutation({
      mutationFn: (vars: TVars) => fn(vars, options?.request),
      ...options?.mutation,
      mutationKey: options?.mutation?.mutationKey || [name],
    });

